mapper.update:
update bus_statement
 set
   total_amount = #{totalAmount,jdbcType=DECIMAL},
   total_quantity = #{totalQuantity,jdbcType=DECIMAL},
   discount_amount = #{discountAmount,jdbcType=DECIMAL}
 where id = #{id,jdbcType=BIGINT}

mapper.select:
select id, customer_name, customer_phone, actual_arrival_time, license_plate, car_series,
service_type, appointment_id, status, pay_time, payee_id, total_amount, total_quantity,
discount_amount, create_time, info, is_delete
from bus_statement


    actual_arrival_time >= #{startTime}


    and actual_arrival_time <= #{endTime}
